import {s,connect,eligible,message} from './accounts.mjs';
import {licenseQuota,hasAvailableCount,claimCount} from './license-quota.mjs';
export async function initFirebaseLicense(){
let b=null,account=null,stop=null,error='',generation=0,authReady=false,serverVerified=false;const verifiedClaims=new Set();
// This account edition requires a live server check before editing. Inventory stays local.
const access={storageKey:'milai-click-v1',business:null,countId:null,season:null,remaining:0};globalThis.milaiAccess=access;
const live=()=>navigator.onLine&&serverVerified&&eligible(account);
const quota=()=>licenseQuota(account);
access.canWrite=session=>live()&&!session?.completedAt&&(!session?.licenseClaimRequired||(session.licenseClaimId===session.id&&verifiedClaims.has(`${b?.auth.currentUser?.uid}:${session.id}`)));access.canStart=()=>live()&&hasAvailableCount(account);
access.acquire=async session=>{if(!session||!live())return false;try{const claimId=await claimCount(s,b.db,b.auth.currentUser.uid,session);verifiedClaims.add(`${b.auth.currentUser.uid}:${claimId}`);await refresh();return true}catch(e){error=message(e);paint();return false}};
access.currentReopenToken=()=>live()&&typeof account?.reopenToken==='string'?account.reopenToken:'';
access.reopenSessionId=()=>live()?account?.reopenClaimId:null;
access.reopenGrant=async session=>{
 if(!session?.completedAt||!live()||account?.reopenClaimId!==session.id||typeof account?.reopenToken!=='string'||!account.reopenToken||session.reopenAppliedToken===account.reopenToken||session.reopenClosedToken===account.reopenToken)return null;
 const uid=b.auth.currentUser.uid,token=account.reopenToken;
 const claim=await s.getDocFromServer(s.doc(b.db,'customerAccounts',uid,'countClaims',session.id));
 if(b.auth.currentUser?.uid!==uid||!live()||account.reopenToken!==token||account.reopenClaimId!==session.id||!claim.exists()||claim.data().sessionId!==session.id)return null;
 verifiedClaims.add(`${uid}:${session.id}`);
 return {sessionId:session.id,token};
};
access.finish=async session=>{if(!session.completedAt&&!access.canWrite(session))throw Error('החשבון אינו פעיל');return session.completedAt||Date.now()};
const bar=document.createElement('section');bar.className='activation-bar';const label=document.createElement('span'),open=document.createElement('button');open.textContent='החשבון שלי';bar.append(label,open);document.querySelector('main').prepend(bar);
const dialog=document.createElement('dialog');dialog.className='account-dialog';dialog.innerHTML=`<button type="button" class="close" aria-label="סגירה">×</button><div class="account-brand">מלאי בקליק</div><h2>מתחילים לספור</h2><p class="account-intro">כניסה לחשבון קיים או הרשמה לעסק חדש</p><div class="account-tabs" role="tablist" aria-label="פעולה"><button type="button" role="tab" class="tab-login" aria-selected="true">כניסה לחשבון</button><button type="button" role="tab" class="tab-register" aria-selected="false">הרשמה חדשה</button></div><p class="status" role="status" aria-live="polite"></p><form><div class="registration-fields" hidden><label>שם העסק<input name="businessName" maxlength="100" placeholder="לדוגמה: מכולת השכונה" autocomplete="organization"></label></div><label>כתובת אימייל<input name="email" type="email" dir="ltr" placeholder="name@example.com" autocomplete="username" required></label><label>סיסמה<div class="password-row"><input name="password" type="password" autocomplete="current-password" required><button type="button" class="show-password" aria-label="הצגת סיסמה">הצג</button></div></label><small class="password-hint" hidden>בחרו סיסמה של 10 תווים לפחות.</small><button class="primary account-submit" name="action" value="login">כניסה לחשבון</button><button type="button" class="reset">שכחתי סיסמה</button></form><div class="account-signed" hidden><strong>החשבון שלכם</strong><p>שם העסק: <b class="signed-business" dir="auto"></b></p><p class="signed-email" dir="ltr"></p><button class="refresh" type="button">בדיקת מצב החשבון</button><button class="logout" type="button">התנתקות</button></div><p class="registration-note" hidden>אחרי ההרשמה, החשבון ממתין לפתיחה על ידי המנהל לאחר בדיקת התשלום.</p><p class="account-footer">הספירות נשמרות במכשיר. נדרש חיבור לאינטרנט לעריכה.</p>`;document.body.append(dialog);
const status=dialog.querySelector('.status'),form=dialog.querySelector('form');
let mode='login';
function setMode(next){mode=next;error='';const register=mode==='register';dialog.querySelector('.registration-fields').hidden=!register;form.elements.businessName.required=register;form.elements.password.minLength=register?10:1;form.elements.password.autocomplete=register?'new-password':'current-password';dialog.querySelector('.password-hint').hidden=!register;dialog.querySelector('.registration-note').hidden=!register;dialog.querySelector('.reset').hidden=register;dialog.querySelector('.account-submit').textContent=register?'יצירת חשבון לעסק':'כניסה לחשבון';dialog.querySelector('.tab-login').setAttribute('aria-selected',String(!register));dialog.querySelector('.tab-register').setAttribute('aria-selected',String(register));status.textContent=register?'מלאו את פרטי העסק כדי ליצור חשבון.':'הזינו את פרטי החשבון שלכם.';}
dialog.querySelector('.tab-login').onclick=()=>setMode('login');dialog.querySelector('.tab-register').onclick=()=>setMode('register');dialog.querySelector('.show-password').onclick=()=>{const input=form.elements.password,show=input.type==='password';input.type=show?'text':'password';dialog.querySelector('.show-password').textContent=show?'הסתר':'הצג'};setMode('login');

function paint(){const active=live(),currentUser=authReady&&!!b?.auth.currentUser,checking=!authReady||!!b?.auth.currentUser&&!serverVerified;access.remaining=live()?Math.max(0,quota().limit-quota().used):0;access.business=serverVerified&&account?{name:account.businessName}:null;const text=checking?(authReady?'בודק את מצב החשבון מול השרת…':'בודק את החיבור לחשבון…'):active?'החשבון פעיל עד '+new Date(account.expiresAt).toLocaleString('he-IL'):!navigator.onLine?'אין חיבור — צפייה וגיבוי זמינים':account?.status==='blocked'?'החשבון חסום — פנה למנהל':account?.status==='pending'?'החשבון ממתין לפתיחה לאחר תשלום':account?.status==='active'?'תוקף החשבון הסתיים':b?.auth.currentUser?'כרטיס העסק טרם נוצר. מלא פרטי עסק ולחץ הרשמה':'יש להתחבר לחשבון';label.textContent=text;status.textContent=error||text;const signed=currentUser&&!!b?.auth.currentUser&&(!!account||!serverVerified);form.hidden=!authReady||signed;dialog.querySelector('.account-tabs').hidden=!authReady||signed;dialog.querySelector('.account-signed').hidden=!signed;dialog.querySelector('.signed-email').textContent=b?.auth.currentUser?.email||'';dialog.querySelector('.signed-business').textContent=currentUser&&serverVerified?(account?.businessName||'לא צוין'):currentUser?'בודק את פרטי העסק…':'';if(signed){dialog.querySelector('.registration-note').hidden=true;dialog.querySelector('h2').textContent='החשבון שלי'}else dialog.querySelector('h2').textContent='מתחילים לספור';bar.dataset.active=String(active);dialog.querySelector('.logout').hidden=!b?.auth.currentUser;document.dispatchEvent(new CustomEvent('milai-license-change'))}
async function ensure(){if(!b){b=await connect();authReady=true;paint()}return b}
async function refresh(){const id=++generation;try{await ensure();if(!b.auth.currentUser){account=null;serverVerified=true;error='';paint();return}const snap=await s.getDocFromServer(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid));if(id!==generation)return;account=snap.exists()?snap.data():null;serverVerified=true;error='';paint()}catch(e){if(id!==generation)return;account=null;serverVerified=false;error=message(e);paint()}}
async function listen(){stop?.();await ensure();if(!b.auth.currentUser)return;stop=s.onSnapshot(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),{includeMetadataChanges:true},snap=>{if(snap.metadata.fromCache){paint();return}generation++;account=snap.exists()?snap.data():null;serverVerified=true;error='';paint()},e=>{generation++;account=null;serverVerified=false;error=message(e);paint()})}
form.onsubmit=async event=>{event.preventDefault();const buttons=[...form.querySelectorAll('button')];buttons.forEach(x=>x.disabled=true);try{await ensure();const fields=new FormData(form),email=fields.get('email').trim(),password=fields.get('password');if(mode==='register'){const businessName=fields.get('businessName').trim();if(!businessName)throw Error('מלא שם עסק');if(password.length<10)throw Error('הסיסמה צריכה להכיל לפחות 10 תווים');if(!b.auth.currentUser||b.auth.currentUser.email!==email)await s.createUserWithEmailAndPassword(b.auth,email,password);const ref=s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),old=await s.getDocFromServer(ref);if(!old.exists())await s.setDoc(ref,{uid:b.auth.currentUser.uid,email:b.auth.currentUser.email,businessName,status:'pending',expiresAt:0,countLimit:1,countsUsed:0,lastClaimId:'',createdAt:s.serverTimestamp()});}else await s.signInWithEmailAndPassword(b.auth,email,password);await refresh();await listen();if(live())dialog.close()}catch(e){error=message(e);paint()}finally{buttons.forEach(x=>x.disabled=false)}};
open.onclick=()=>{paint();dialog.showModal()};dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('.refresh').onclick=()=>refresh();dialog.querySelector('.logout').onclick=async()=>{generation++;account=null;serverVerified=false;stop?.();if(b)await s.signOut(b.auth);paint()};dialog.querySelector('.reset').onclick=async()=>{try{await ensure();const email=form.elements.email.value.trim();if(!email)throw Error('הזן אימייל');await s.sendPasswordResetEmail(b.auth,email);status.textContent='אם החשבון קיים, יישלח מייל איפוס'}catch(e){status.textContent=message(e)}};
window.addEventListener('offline',()=>{generation++;account=null;serverVerified=false;paint()});window.addEventListener('online',async()=>{serverVerified=false;await refresh();await listen()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});setInterval(()=>{paint();if(navigator.onLine)refresh()},60000);paint();ensure().then(async()=>{await refresh();await listen()}).catch(e=>{authReady=true;error=message(e);paint()});return access;
}
